+} from '../../types/index.ts';
+import { _getStandardProps } from '../../utils/index.ts';
+
+/**
+ * Recursive schema placeholder interface.
+ *
+ * @internal
+ */
+export interface RecurSchema extends BaseSchema<RecurSchema, RecurSchema, never> {
+  /**
+   * The schema type.
+   */
+  readonly type: 'recur';
+  /**
+   * The schema reference.
+   */
+  readonly reference: typeof recursive;
+  /**
+   * The expected property.
+   */
+  readonly expects: 'unknown';
+}
+
+/**
+ * Placeholder for a self reference in a recursive schema.
+ */
+export const Recur: RecurSchema = {
+  kind: 'schema',
+  type: 'recur',
+  reference: recursive,
+  expects: 'unknown',
+  async: false,
+  get '~standard'() {
+    return _getStandardProps(this);
+  },
+  '~run'() {
+    throw new TypeError('Recursive schema must be wrapped with recursive().');
+  },
+};
+
+type ReplaceRecur<TValue, TRecur> = TValue extends RecurSchema
+  ? TRecur
+  : TValue extends readonly (infer TItem)[]
+    ? TValue extends (infer TItem)[]
+      ? ReplaceRecur<TItem, TRecur>[]
+      : readonly ReplaceRecur<TItem, TRecur>[]
+    : TValue extends Map<infer TKey, infer TValue>
+      ? Map<ReplaceRecur<TKey, TRecur>, ReplaceRecur<TValue, TRecur>>
+      : TValue extends Set<infer TItem>
+        ? Set<ReplaceRecur<TItem, TRecur>>
+        : TValue extends object
+          ? { [TKey in keyof TValue]: ReplaceRecur<TValue[TKey], TRecur> }
+          : TValue;
+
+type RecursiveInput<TWrapped extends BaseSchema<unknown, unknown, BaseIssue<unknown>>> =
+  ReplaceRecur<InferInput<TWrapped>, RecursiveInput<TWrapped>>;
+
+type RecursiveOutput<
+  TWrapped extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
+> = ReplaceRecur<InferOutput<TWrapped>, RecursiveOutput<TWrapped>>;
+
+/**
+ * Recursive schema interface.
+ */
+export interface RecursiveSchema<
+  TWrapped extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
+> extends BaseSchema<
+    RecursiveInput<TWrapped>,
+    RecursiveOutput<TWrapped>,
+    InferIssue<TWrapped>
+  > {
+  /**
+   * The schema type.
+   */
+  readonly type: 'recursive';
+  /**
+   * The schema reference.
+   */
+  readonly reference: typeof recursive;
+  /**
+   * The expected property.
+   */
+  readonly expects: 'unknown';
+  /**
+   * The wrapped schema.
+   */
+  readonly wrapped: TWrapped;
+}
+
+/**
+ * Creates a recursive schema.
+ *
+ * @param wrapped The schema containing recursive placeholders.
+ *
+ * @returns A recursive schema.
+ */
+// @__NO_SIDE_EFFECTS__
+export function recursive<
+  const TWrapped extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
+>(wrapped: TWrapped): RecursiveSchema<TWrapped> {
+  let schema: RecursiveSchema<TWrapped>;
+  const resolved = _resolveRecur(wrapped, () => schema);
+  schema = {
+    kind: 'schema',
+    type: 'recursive',
+    reference: recursive,
+    expects: 'unknown',
+    async: false,
+    wrapped,
+    get '~standard'() {
+      return _getStandardProps(this);
+    },
+    '~run'(dataset, config) {
+      return resolved['~run'](dataset, config) as OutputDataset<
+        RecursiveOutput<TWrapped>,
+        InferIssue<TWrapped>
+      >;
+    },
+  };
+  return schema;
+}
+
+/**
+ * Replaces recursive placeholders in a schema.
+ *
+ * @internal
+ */
+export function _resolveRecur<TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>>(
+  schema: TSchema,
+  getRecur: () => BaseSchema<unknown, unknown, BaseIssue<unknown>>
+): TSchema {
+  if (schema === Recur) {
+    return getRecur() as TSchema;
+  }
+
+  if ('pipe' in schema) {
+    const pipe = schema.pipe.map((item) =>
+      item.kind === 'schema' ? _resolveRecur(item, getRecur) : item
+    );
+    return schema.reference(...pipe) as TSchema;
+  }
+
+  const resolved = { ...schema } as Record<string, unknown>;
+  if ('item' in schema) resolved.item = _resolveRecur(schema.item, getRecur);
+  if ('key' in schema && schema.key && typeof schema.key === 'object' && 'kind' in schema.key) {
+    resolved.key = _resolveRecur(schema.key, getRecur);
+  }
+  if ('value' in schema && schema.value && typeof schema.value === 'object' && 'kind' in schema.value) {
+    resolved.value = _resolveRecur(schema.value, getRecur);
+  }
+  if ('wrapped' in schema) resolved.wrapped = _resolveRecur(schema.wrapped, getRecur);
+  if ('rest' in schema && schema.rest) resolved.rest = _resolveRecur(schema.rest, getRecur);
+  if ('items' in schema) resolved.items = schema.items.map((item) => _resolveRecur(item, getRecur));
+  if ('options' in schema && Array.isArray(schema.options) && schema.options.every((item) => item && typeof item === 'object' && 'kind' in item)) {
+    resolved.options = schema.options.map((item) => _resolveRecur(item, getRecur));
+  }
+  if ('entries' in schema) {
+    resolved.entries = Object.fromEntries(
+      Object.entries(schema.entries).map(([key, value]) => [
+        key,
+        _resolveRecur(value, getRecur),
+      ])
+    );
+  }
+  return resolved as TSchema;
+}
